targets.expr:
sum by (cluster, queue) (
label_replace(
  label_replace(
  label_replace(
  label_replace(
  max by (cluster, bucket) (minio_cluster_usage_buckets_total_bytes{cluster="$cluster", bucket=~"ic-.*"}),
  "queue", "root.platform", "bucket", "^(ic-platform)$"
),
  "queue", "root.fdc", "bucket", "^(ic-fdc|ic-lfdc)$"
),
  "queue", "root.tttm", "bucket", "^(ic-tttm)$"
),
  "queue", "root.pluto", "bucket", "^(ic-pluto)$"
)
)

