function tagSrc(html){
  return html.replace(/<tr([^>]*)><td class="(mx-lab[^"]*)">([\s\S]*?)<\/td>/g,
    function(m, attrs, cls, inner){
      /* 라벨 키 = 단위 보조문구(.mx-u)를 뺀 순수 텍스트 */
      const key = inner.replace(/<span class="mx-u">[\s\S]*?<\/span>/g, '')
                       .replace(/<[^>]*>/g, '').trim();
      const s = SRC[key];
      if (!s) return m;   /* 미등록 라벨은 배지 없이 통과 — 누락이 눈에 띄도록 */
      const a = attrs.indexOf('class="') >= 0
        ? attrs.replace('class="', 'class="mx-r-' + s + ' ')
        : attrs + ' class="mx-r-' + s + '"';
      return '<tr' + a + '><td class="' + cls + '">'
           + '<span class="src ' + s + '">' + SRC_LBL[s] + '</span>' + inner + '</td>';
    });
}
const SRC_LEGEND = "<div class=\"srcleg\"><span class=\"it\"><span class=\"src doc\">\ubb38\uc11c</span> <b>\ud558\ub4dc\ucf54\ub529</b> \u2014 \uc6d0\ubcf8 \ubc30\ubd84\ud45c(<code>team-dashboard.md</code>) \uc804\uc0ac\uac12. \ucd9c\ucc98 \uba54\ud2b8\ub9ad\uc774 \uc5c6\uc5b4 \uc0ac\ub78c\uc774 \uc62e\uaca8 \uc801\uc5c8\ub2e4. \uc870\ud68c \uc2dc\uc810\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uac19\uc740 \uac12\uc774\uba70, \uc2e4\uc81c \ud074\ub7ec\uc2a4\ud130 \uc124\uc815\uacfc \uc5b4\uae0b\ub098 \uc788\uc5b4\ub3c4 \ud654\uba74\uc740 \uadf8\ub300\ub85c\ub2e4.</span><span class=\"it\"><span class=\"src live\">\uc2e4\uce21</span> <b>PromQL \uc870\ud68c\uac12</b> \u2014 <code>yunikorn_queue_resource</code> / <code>yunikorn_queue_app</code> / <code>minio_cluster_usage_buckets_total_bytes</code> \ub97c \ub300\uc2dc\ubcf4\ub4dc \uc2dc\uac04\ubc94\uc704\ub85c \uc870\ud68c\ud574 \uacc4\uc0b0. <span class=\"src na\">\ubbf8\uae30\uc7ac</span> \ub294 \uc6d0\ubcf8 \ud45c\uc5d0 \ud589\ub9cc \uc788\uace0 \uac12\uc774 \ube44\uc5b4 \uc788\ub294 \ud56d\ubaa9\uc774\ub2e4.</span><span class=\"it\">\u26a0 <b>\ubb38\uc11c \ubcf4\uc7a5\uc790\uc6d0\uacfc \uc2e4\uce21 \ubcf4\uc7a5(guaranteed)\uc740 \uc11c\ub85c \ub2e4\ub978 \uc218\ub2e4.</b> \ubb38\uc11c\ub294 \ubc30\ubd84 \uacc4\ud68d(\ud569 10,840 vCores), \uc2e4\uce21\uc740 \uc774 \ub7a9 YuniKorn \ud050\uc5d0 \uc2e4\uc81c\ub85c \uac78\ub9b0 \uac12\uc774\ub2e4 \u2014 \uc0ac\uc6a9\ub960\u00b7\uc0c1\ud0dc \ud310\uc815\uc740 \uc804\ubd80 <b>\uc2e4\uce21</b> \uae30\uc900\uc774\ub2e4.</span></div>";

/* Business Text v6 실행 규약 (소스 실측):
     - 이 코드는 new Function('context', code) 로 실행된다 → 변수명은 context.
     - **반환값은 렌더에 쓰이지 않는다.** 실제 렌더는 content(Handlebars) 가 한다.
       → 여기서는 handlebars helper 를 등록하고, content 에서 {{{matrix}}} 로 부른다.
     - renderMode='data' 일 때 panelData.series 에 전 refId 프레임이 들어온다.
     - 최종 HTML 은 DOMPurify(USE_PROFILES:{html:true}) 를 통과한다
       → table/td/colspan/class/style 은 살아남고 script/on* 은 제거된다. */
/* ── 플러그인 API 호환 shim (버전 차이로 조용히 빈 패널이 되는 걸 막는다) ──
   Business Text v6 : new Function('context', code) → context.{handlebars, panelData}
   구버전(v4/v5)     : handlebars / panelData / data 가 **개별 변수**로 들어온다.
   폐쇄망처럼 미러된 구버전이 깔리면 `context` 가 없어 ReferenceError 로 죽고,
   helper 가 등록되지 않아 패널이 **에러 없이 텅** 빈다.
   typeof 가드라 없는 식별자를 참조해도 안전하다. */
var __BTCTX = (typeof context !== 'undefined' && context) ? context : {};
var __BTH = __BTCTX.handlebars || (typeof handlebars !== 'undefined' ? handlebars : null);
var __BTS = (__BTCTX.panelData && __BTCTX.panelData.series)
         || (typeof panelData !== 'undefined' && panelData && panelData.series)
         || (typeof data !== 'undefined' && data && data.series) || [];
const H = __BTH;
const COLORS = {"AI/Data Platform":"#2a78d6","품질 지능화":"#eb6834",
                "EES/MDM/IPA":"#1baf7a","장비 지능화":"#eda100"};
const ORDER = ["root.platform","root.fdc","root.smartbig","root.yms","root.tttm","root.pluto"];

/* 원본 배분표(team-dashboard.jpg / .md)의 '전체리소스 Total(vCores)' 열.
   메트릭 출처가 없다 — 엑셀에만 있는 문서값이라 여기 상수로 둔다(룰 판·룰미사용 판 공통).
   ⚠ app/sql 은 서비스 열 합과 어긋난다(문서 자체의 불일치):
        app  6,768 vs 열 합 6,500 (Δ268)   ·   sql 4,240 vs 열 합 4,140 (Δ100)
   그래서 표에서는 '문서값 (합계)' 형태로 **둘 다** 보여주고 어긋나면 표시한다. */
const PLAN_TOTAL = {spark:6768, trino:4240, guar:10840, shared:3384};

/* 원본 배분표의 '비율' 행 — **팀 단위 병합 셀**이다(PLATFORM+FDC, SMARTBIG+YMS).
   ⚠ 이 비율의 분모는 표의 어느 합계와도 맞지 않는다(역산 시 약 13,530; 네 팀 합이 정확히 80.00%).
   그래서 문서값 그대로 싣되, 계산이 분명한 '전체 비중(보장 기준)' 행을 따로 둔다. */
const DOC_RATIO = {total:"100.00%", pairs:[["root.platform","root.fdc","23%"],
                                           ["root.smartbig","root.yms","35.10%"]],
                   single:{"root.tttm":"5.10%", "root.pluto":"16.80%"}};

/* refId 별 프레임을 큐 기준 레코드로 정규화.

   ⚠ 프레임 형태가 두 가지일 수 있다 (실측 근거):
     (a) time_series 형태 — refId 당 시리즈마다 프레임 1개, **라벨이 값 필드에** 붙는다.
         /api/ds/query(백엔드 직접 호출)로 확인한 실제 모양이 이것이다.
     (b) table 형태 — 라벨이 컬럼으로 펼쳐진 프레임 1개.
         format:"table" 은 Prometheus **프론트엔드** 데이터소스가 적용하므로
         패널 안에서는 이쪽이 올 수 있다.
   어느 쪽이 올지 렌더 없이 확정할 수 없어 **둘 다 처리**한다. */
function arr(f){ return (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []); }

function collect(series, refId){
  const out = {};
  series.filter(s => s.refId === refId).forEach(f => {
    const names = (f.fields || []).map(x => x.name);
    const qi = names.indexOf("queue");

    if (qi >= 0) {                                   /* (b) table 형태 */
      const cols = {};
      names.forEach((n,i) => { cols[n] = arr(f.fields[i]); });
      let vn = names.find(n => n === "Value" || n.indexOf("Value") === 0);
      if (!vn) vn = names.find(n => n !== "Time" && f.fields[names.indexOf(n)].type === "number");
      (cols["queue"] || []).forEach((q, r) => {
        const rec = out[q] || (out[q] = {});
        names.forEach(n => { if (n !== "Time") rec[n] = cols[n][r]; });
        if (vn) rec.__v = cols[vn][r];
      });
      return;
    }

    /* (a) time_series 형태 — 라벨이 값 필드에 */
    const vf = (f.fields || []).find(x => x.type === "number")
            || (f.fields || [])[(f.fields || []).length - 1];
    const lab = (vf && vf.labels) || {};
    if (!lab.queue) return;
    const rec = out[lab.queue] || (out[lab.queue] = {});
    Object.keys(lab).forEach(k => { rec[k] = lab[k]; });
    const vs = arr(vf);
    rec.__v = vs.length ? vs[vs.length - 1] : null;
  });
  return out;
}
const val = (m) => { const o = {}; Object.keys(m).forEach(q => { o[q] = m[q].__v; }); return o; };

const S = __BTS;
const meta = INFO;
/* collect() 는 queue 라벨도 레코드에 넣어줬다 — 하드코딩 표엔 없으니 키에서 채운다 */
Object.keys(meta).forEach(q => { meta[q].queue = q; });
