};
/* ★ 행 순서는 원본 배분표(team-dashboard.md)를 그대로 따른다.
     LDAP → Bucket 구성 → SQL Engine → Trino Catalog
     → app 서비스 · Trino 활용방안 · Trino 리소스 제어 (원본에서 값이 비어 있는 행)
     → Schedule Queue → 워크로드 분류
   예전엔 Bucket 구성과 Schedule Queue 가 뒤바뀌어 있었다. */
const txtRow = (lbl, key, mergeSY) => {
  let r = '<tr><td class="mx-lab">'+lbl+'</td>'+TOT_EMPTY;
  for (let i=0;i<queues.length;i++){
