         + '<div class="mx-note">SMARTBIG + YMS 공통</div></td>'; i++;
    } else {
      const v = meta[q][key];
      r += '<td class="mx-c mx-txt">'+(v ? v : '<span class="mx-dim">—</span>')+'</td>';
    }
  }
  return r+'</tr>';
};
h += rowTag("LDAP","ldap");
