h += txtRow("Trino Catalog","catalog", true);   /* 원본에서 SMARTBIG+YMS 병합 */
/* 원본에 행은 있으나 값이 전부 비어 있는 항목 — 표 구조를 그대로 재현하되 '미기재'로 명시 */
['app 서비스','Trino 활용방안','Trino 리소스 제어'].forEach(lbl => {
  h += '<tr><td class="mx-lab mx-dim">'+lbl+'</td>'+TOT_EMPTY
     + '<td class="mx-c mx-dim mx-merge" colspan="'+queues.length+'">원본 배분표 미기재</td></tr>';
});
h += rowTag("Schedule Queue","queue");
h += txtRow("워크로드 분류","workload");

/* ── 배분 계획값 (섹션 머리 + 병합 셀) ── */
/* 전체리소스 셀: 문서값을 보여주되 서비스 열의 합과 다르면 (합계 …) 를 덧붙인다.
   원본 배분표의 app/sql Total 이 열 합과 안 맞아서(Δ268/Δ100) 어느 한쪽만 쓰면 거짓말이 된다. */
function totCell(docVal, map, dec){
  const sum = queues.reduce((a,q)=> a + (map[q]||0), 0);
  let s = '<td class="mx-c mx-num mx-tot">'+(docVal==null?fmt(sum,dec):fmt(docVal));
  if (docVal!=null && Math.round(docVal)!==Math.round(sum))
    s += '<div class="mx-note mx-warn2">합계 '+fmt(sum)+'</div>';
  return s+'</td>';
}
h += '<tr class="mx-sec"><td class="mx-lab">APACHE SPARK vCores</td>'+totCell(PLAN_TOTAL.spark, spark);
queues.forEach(q => { h += '<td class="mx-c mx-num">'+fmt(spark[q])+'</td>'; });
h += '</tr>';

/* Trino·Pod 은 SMARTBIG+YMS 가 원본 표에서 병합 셀 → colspan 으로 재현 */
function mergedRow(label, map, note, docTotal, xForNull){
  let r = '<tr><td class="mx-lab">'+label+'</td>'
        + (docTotal===undefined ? TOT_EMPTY : totCell(docTotal, map));
  for (let i=0;i<queues.length;i++){
    const q=queues[i];
    if (q==="root.smartbig" && queues[i+1]==="root.yms"){
      r += '<td class="mx-c mx-num mx-merge" colspan="2">'+fmt(map[q])
         + '<div class="mx-note">'+note+'</div></td>'; i++;
    } else if (map[q]==null){
      /* 원본 표는 Trino vCores 칸에만 'X'(SQL 엔진 없음)를 적는다. Pod 수의 빈칸은 미기재라 —. */
      r += '<td class="mx-c mx-num">'
         + (xForNull && meta[q].sql_engine==="X" ? '<b class="mx-x">X</b>' : "—")+'</td>';
    } else r += '<td class="mx-c mx-num">'+fmt(map[q])+'</td>';
  }
  return r+'</tr>';
}
h += mergedRow("Trino vCores", trino, "SMARTBIG + YMS 공통", PLAN_TOTAL.trino, true);
h += mergedRow("Pod 수", planpods, "SMARTBIG + YMS 공통");

h += '<tr class="mx-sec"><td class="mx-lab">보장자원 GUARANTEED</td>'+totCell(PLAN_TOTAL.guar, guar);
queues.forEach(q => { h += '<td class="mx-c mx-num">'+fmt(guar[q])+'</td>'; });
h += '</tr>';
/* 공용자원 — 팀에 귀속되지 않는 공유 풀. 원본 표에서 전 열 병합 셀이라 colspan 으로 재현 */
h += '<tr><td class="mx-lab">공용자원 <span class="mx-u">shared</span></td>'
   + '<td class="mx-c mx-num mx-tot">'+fmt(PLAN_TOTAL.shared)+'</td>'
   + '<td class="mx-c mx-num mx-merge" colspan="'+queues.length+'">'
   + '<span class="mx-dim">전 팀 공용 (팀 미귀속) · OverCommit 여유분</span></td></tr>';

/* ── 실측 사용 행 (값 + % + 막대) ── */
/* ── 여기부터는 원본 배분표에 없는 랩 실측/설정 값 ──
   한계 LIMIT (state=max): 버스트 상한. 합이 클러스터 용량을 넘는 만큼이 OverCommit. */
h += '<tr class="mx-sec"><td class="mx-lab">한계 <span class="mx-u">max · 랩</span></td>';
(function(){
  const sum = queues.reduce((a,q)=> a + (lim[q]||0), 0);
  const ratio = capacity ? sum/capacity*100 : null;
  h += '<td class="mx-c mx-num mx-tot">'+fmt(sum,2)
     + (ratio!=null ? '<div class="mx-note '+(ratio>100?'mx-warn2':'')+'">용량 '+fmt(capacity,2)
        +' · '+ratio.toFixed(0)+'%</div>' : '')+'</td>';
})();
queues.forEach(q => { h += '<td class="mx-c mx-num">'+(lim[q]==null?"—":fmt(lim[q],2))+'</td>'; });
h += '</tr>';
h += '<tr><td class="mx-lab">CPU 사용 <span class="mx-u">cores</span></td>'+totCell(null, lu, 2);
queues.forEach(q => { h += useCell(lu[q], lq[q], 2); });
h += '</tr>';
/* 대기 PENDING (state=pending) — 자원이 모자라 못 뜬 요구량. 0 과 '관측 없음'을 구분한다. */
h += '<tr><td class="mx-lab">대기 <span class="mx-u">pending cores</span></td>'+totCell(null, pend, 2);
queues.forEach(q => { const v=pend[q];
  h += '<td class="mx-c mx-num'+(v>0?" mx-ovf":"")+'">'+(v==null?"—":fmt(v,2))+'</td>'; });
h += '</tr>';
h += '<tr><td class="mx-lab">Memory 사용 <span class="mx-u">GiB</span></td>'+TOT_EMPTY;
queues.forEach(q => { const u=mu[q]!=null?mu[q]/1073741824:null, k=mq[q]!=null?mq[q]/1073741824:null;
  h += useCell(u, k, 1); });
h += '</tr>';
/* S3 사용 — ic-* 버킷 합계.
   ★ 품질 지능화(SMARTBIG+YMS)의 13개 버킷은 **팀 단위로만** 귀속이 정의돼 서비스로 못 쪼갠다
     → 원본 표가 이 팀의 Trino·Pod 을 병합 셀로 적은 것과 같은 규칙으로 colspan 병합한다.
   메트릭 미수집 환경에선 전부 '—'(관측 없음, 0 아님). */
h += '<tr><td class="mx-lab">S3 사용 <span class="mx-u">GiB</span></td>';
(function(){
  const g = v => (v==null ? null : v/1073741824);
  const teamShared = g(s3shared);
  let tot = 0, any = false;
  queues.forEach(q => { if (q!=="root.yms" && s3[q]!=null){ tot += s3[q]/1073741824; any=true; } });
  if (teamShared!=null){ tot += teamShared; any = true; }
  h += '<td class="mx-c mx-num mx-tot">'+(any?fmt(tot,1):'<span class="mx-dim">—</span>')+'</td>';
  for (let i=0;i<queues.length;i++){
    const q=queues[i];
    if (q==="root.smartbig" && queues[i+1]==="root.yms"){
      h += '<td class="mx-c mx-num mx-merge" colspan="2">'
         + (teamShared==null?'<span class="mx-dim">—</span>':fmt(teamShared,1))
         + '<div class="mx-note">SMARTBIG + YMS 공통 (13개 버킷)</div></td>'; i++;
    } else {
      const v = g(s3[q]);
      h += '<td class="mx-c mx-num">'+(v==null?'<span class="mx-dim">—</span>':fmt(v,1))+'</td>';
    }
  }
})();
h += '</tr>';
h += '<tr><td class="mx-lab">공용 차용 <span class="mx-u">cores</span></td>'+totCell(null, ovf, 2);
queues.forEach(q => { const v=ovf[q];
  h += '<td class="mx-c mx-num'+(v>0?" mx-ovf":"")+'">'+(v==null?"—":fmt(v,2))+'</td>'; });
h += '</tr>';
h += '<tr><td class="mx-lab">실행 파드</td>'+totCell(null, pods);
queues.forEach(q => { h += '<td class="mx-c mx-num">'+(pods[q]==null?"—":fmt(pods[q]))+'</td>'; });
h += '</tr>';

/* ── 상태 · 비중 ── */
h += '<tr><td class="mx-lab">상태</td>'+TOT_EMPTY;
queues.forEach(q => { const p=pct(lu[q],lq[q]); const [cls,lbl]=stat(p);
  h += '<td class="mx-c">'+(p==null?'<span class="mx-dim">—</span>'
     : '<span class="mx-pill '+cls+'">'+lbl+' '+p.toFixed(0)+'%</span>')+'</td>'; });
h += '</tr>';
/* 원본 배분표의 '비율' 행 — 팀 단위 병합 셀 그대로 */
h += '<tr><td class="mx-lab">비율 <span class="mx-u">원본 문서값</span></td>'
   + '<td class="mx-c mx-num mx-tot">'+DOC_RATIO.total+'</td>';
for (let i=0;i<queues.length;i++){
  const q=queues[i], nx=queues[i+1];
  const pair = DOC_RATIO.pairs.filter(p => p[0]===q && p[1]===nx)[0];
  if (pair){ h += '<td class="mx-c mx-num mx-merge" colspan="2">'+pair[2]+'</td>'; i++; }
  else h += '<td class="mx-c mx-num">'+(DOC_RATIO.single[q]||"—")+'</td>';
}
h += '</tr>';
h += '<tr class="mx-sec"><td class="mx-lab">전체 비중 <span class="mx-u">보장 기준</span></td>'+'<td class="mx-c mx-num mx-tot">100.0%</td>';
queues.forEach(q => { h += '<td class="mx-c mx-num">'+(totGuar?((guar[q]/totGuar*100).toFixed(1)+"%"):"—")+'</td>'; });
h += '</tr>';

h += '</tbody></table>';
h += '<div class="mx-legend">'
  +  '<span><i class="sw ok"></i>보장 범위 내 사용</span>'
  +  '<span><i class="sw hatch"></i>공용자원에서 끌어쓴 몫</span>'
  +  '<span class="mx-dim">회색 배경 = 원본 표의 병합 셀 — Trino Catalog·Trino vCores·Pod 수(SMARTBIG+YMS), 공용자원(전체), 비율(팀 단위)</span>'
  +  '<span class="mx-dim">state: 보장 guaranteed · 한계 max · 사용 allocated · 대기 pending</span>'
  +  '</div>';

MATRIX_HTML = tagSrc(h) + SRC_LEGEND;
H.registerHelper('matrix', () => new H.SafeString(MATRIX_HTML));

