options.helpers:
/* ── 플러그인 API 호환 shim (버전 차이로 조용히 빈 패널이 되는 걸 막는다) ──
   Business Text v6 : new Function('context', code) → context.{handlebars, panelData}
   구버전(v4/v5)     : handlebars / panelData / data 가 **개별 변수**로 들어온다.
   폐쇄망처럼 미러된 구버전이 깔리면 `context` 가 없어 ReferenceError 로 죽고,
   helper 가 등록되지 않아 패널이 **에러 없이 텅** 빈다.
   typeof 가드라 없는 식별자를 참조해도 안전하다. */
var __BTCTX = (typeof context !== 'undefined' && context) ? context : {};
var __BTH = __BTCTX.handlebars || (typeof handlebars !== 'undefined' ? handlebars : null);
var __BTS = (__BTCTX.panelData && __BTCTX.panelData.series)
         || (typeof panelData !== 'undefined' && panelData && panelData.series)
         || (typeof data !== 'undefined' && data && data.series) || [];
const H = __BTH;
const COLORS = {"AI/Data Platform":"#2a78d6","품질 지능화":"#eb6834",
                "EES/MDM/IPA":"#1baf7a","장비 지능화":"#eda100"};
const TEAM_ORDER = ["AI/Data Platform","품질 지능화","EES/MDM/IPA","장비 지능화"];
function arr(f){ return (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []); }

/* refId 프레임 → {팀: 값}. table/time_series 두 형태 모두 처리. */
function byTeam(series, refId){
  const out = {};
  series.filter(s => s.refId === refId).forEach(f => {
    const names = (f.fields||[]).map(x=>x.name);
    const ti = names.indexOf("team");
    if (ti >= 0) {
      const teams = arr(f.fields[ti]);
      let vn = names.find(n => n === "Value" || n.indexOf("Value") === 0)
            || names.find(n => n !== "Time" && f.fields[names.indexOf(n)].type === "number");
      const vals = vn ? arr(f.fields[names.indexOf(vn)]) : [];
      teams.forEach((tm,i)=>{ out[tm] = vals[i]; });
      return;
    }
    const vf = (f.fields||[]).find(x=>x.type==="number") || (f.fields||[])[(f.fields||[]).length-1];
    const lab = (vf && vf.labels) || {};
    if (!lab.team) return;
    const vs = arr(vf);
    out[lab.team] = vs.length ? vs[vs.length-1] : null;
  });
  return out;
}
function scalarOf(series, refId){
  const m = byTeam(series, refId);
  const k = Object.keys(m);
  if (k.length) return m[k[0]];
  const f = series.filter(s=>s.refId===refId)[0];
  if (!f) return null;
  const vf = (f.fields||[]).find(x=>x.type==="number");
  const vs = arr(vf); return vs && vs.length ? vs[vs.length-1] : null;
}

const S = __BTS;
const q = byTeam(S, "teamq");
const teams = TEAM_ORDER.filter(t => q[t] != null);
const fmt = v => v==null||isNaN(v) ? "—" : Number(v).toLocaleString("ko-KR",{maximumFractionDigits:2});

if (!teams.length) {
  H.registerHelper('share', () => new H.SafeString(
    '<div style="padding:14px;opacity:.7">데이터 없음 — frames=' + S.length
    + ' refIds=' + S.map(s=>s.refId).join(",") + '</div>'));
  return;
}
const tot = teams.reduce((a,t)=>a+q[t],0);
const shared = scalarOf(S, "shared");

let h = '<div class="sh-wrap"><div class="sh-bar">';
teams.forEach(t => {
  const pc = q[t]/tot*100;
  h += '<div class="sh-seg" style="flex:'+pc.toFixed(4)+';background:'+(COLORS[t]||"#8a93a3")+'">'
     + (pc >= 7 ? pc.toFixed(1)+'%' : '') + '</div>';
});
h += '</div><div class="sh-legend">';
teams.forEach(t => {
  h += '<span><i style="background:'+(COLORS[t]||"#8a93a3")+'"></i>'+t
     + ' <b>'+fmt(q[t])+'</b></span>';
});
if (shared != null) h += '<span class="sh-dim"><span class="src doc">문서</span> 공용자원 <b>'+fmt(shared)+'</b> (팀 미귀속 · 출처 메트릭 없는 상수)</span>';
h += '</div><div class="sh-tot">합계 <b>'+fmt(tot)+'</b> cores</div></div>';

H.registerHelper('share', () => new H.SafeString(h));

