.sh-seg{display:flex;align-items:center;justify-content:center;border-radius:2px;
  font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11.5px;font-weight:700;
  color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.45);min-width:2px}
.sh-seg:first-child{border-radius:4px 2px 2px 4px}
.sh-seg:last-child{border-radius:2px 4px 4px 2px}
.sh-legend{display:flex;gap:16px;flex-wrap:wrap;font-size:11.5px;margin-top:10px;opacity:.9}
.sh-legend i{width:10px;height:10px;border-radius:2px;display:inline-block;margin-right:6px;
  vertical-align:-1px}
.sh-legend b{font-family:ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
.sh-dim{opacity:.6}
.sh-tot{font-size:11.5px;opacity:.6;margin-top:6px;
  font-family:ui-monospace,Menlo,Consolas,monospace}

.src{display:inline-block;font-size:9.5px;font-weight:700;line-height:15px;
     padding:0 6px;border-radius:3px;letter-spacing:.02em;vertical-align:1px;color:#fff;
     font-family:system-ui,-apple-system,"Segoe UI","Noto Sans KR","Malgun Gothic",sans-serif}
.src.doc{background:#9a6f18}
.src.live{background:#2a68b8}
.src.na{background:#6b7280}
.srcleg{display:flex;gap:8px 18px;flex-wrap:wrap;font-size:11px;margin-top:11px;
        padding-top:9px;border-top:1px solid rgba(128,138,155,.22);line-height:1.65;opacity:.85}
.srcleg span.it{display:block;max-width:520px}
.srcleg code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:10.5px;
        padding:1px 5px;border-radius:3px;background:rgba(128,138,155,.16)}
